//! Tall buildings: storey limits follow the height rule, curtain walls are generated by the
//! facade rules, the sprinkler system covers the rooms and is one connected, sized network,
//! and the lift core grows with the passenger traffic.

use ddc_gen::project::{build_project, check_project, hazard_of, parse_spec, FireRun, GProject, ProjectSpec, RoomKind};
use serde_json::{json, Value as J};

type P2 = (f64, f64);

fn inside(poly: &[P2], q: P2) -> bool {
    let mut c = false;
    for i in 0..poly.len() {
        let (a, b) = (poly[i], poly[(i + 1) % poly.len()]);
        if (a.1 > q.1) != (b.1 > q.1) && q.0 < (b.0 - a.0) * (q.1 - a.1) / (b.1 - a.1) + a.0 {
            c = !c;
        }
    }
    c
}

fn area(poly: &[P2]) -> f64 {
    let n = poly.len();
    (0..n).map(|i| poly[i].0 * poly[(i + 1) % n].1 - poly[(i + 1) % n].0 * poly[i].1).sum::<f64>().abs() / 2.0
}

fn built(v: J) -> (ProjectSpec, GProject) {
    let s = parse_spec(&v).unwrap_or_else(|e| panic!("{e}"));
    let p = build_project(&s).unwrap_or_else(|e| panic!("{e}"));
    (s, p)
}

fn office(floors: u32, extra: J) -> J {
    let mut v = json!({"typology": "office", "floors": floors});
    for (k, x) in extra.as_object().unwrap() {
        v[k] = x.clone();
    }
    v
}

#[test]
fn sixty_four_storeys_are_accepted_and_reach_the_roof() {
    let (s, p) = built(office(64, json!({})));
    assert_eq!(p.storeys.len(), 64);
    assert!((p.roof.elevation - 64.0 * s.floor_height).abs() < 1e-6);
    let g = check_project(&s, &p);
    assert!(g.passed(), "{:?}", g.failures);
    // the tallest building keeps its sprinkler and standpipe pipes within their slot blocks
    use ddc_gen::project::slots::*;
    let sp: usize = p.fire.standpipes.iter().map(|x| x.runs.len()).sum();
    assert!(sp > 0 && sp <= STANDPIPE_MAX as usize, "{sp} standpipe pipes");
    assert!(p.fire.runs.len() <= SPRINKLER_RUNS as usize, "{} sprinkler pipes", p.fire.runs.len());
    // the last sprinkler slot lies below the first standpipe slot
    assert_eq!(STANDPIPE - (SPRINKLER + SPRINKLER_RUNS - 1), 1);
}

#[test]
fn the_height_rule_caps_the_storeys() {
    // the type rule alone allows 200; a 150 m height limit with 3 m storeys stops at 50
    let v = office(60, json!({"rules": {"massing.height_max": 150}}));
    let e = parse_spec(&v).unwrap_err().to_string();
    assert!(e.contains("floors"), "{e}");
    let ok = office(50, json!({"rules": {"massing.height_max": 150}, "floor_height": 3.0}));
    assert!(parse_spec(&ok).is_ok());
    let e = parse_spec(&office(201, json!({}))).unwrap_err().to_string();
    assert!(e.contains("floors"), "{e}");
}

#[test]
fn the_curtain_facade_makes_curtain_walls_with_spandrels() {
    let (_, p) = built(office(6, json!({"design": {"facade": "curtain"}})));
    let walls: usize = p.storeys.iter().map(|s| s.curtains.len()).sum();
    assert!(walls > 0, "no curtain wall was generated");
    for c in p.storeys.iter().flat_map(|s| &s.curtains) {
        assert!(c.spandrel > 0.0 && c.spandrel < c.height, "spandrel {}", c.spandrel);
        assert!(c.spacing.0 > 0.0 && c.mullion.0 > 0.0);
        let len = (c.b.0 - c.a.0).hypot(c.b.1 - c.a.1);
        assert!(len > 0.0);
    }
    let (_, plain) = built(office(6, json!({"design": {"facade": "punched"}})));
    assert!(plain.storeys.iter().all(|s| s.curtains.is_empty()));
}

#[test]
fn sprinkler_heads_cover_the_rooms_and_the_network_is_connected() {
    let (_, p) = built(office(30, json!({"floors": 30})));
    let f = &p.fire;
    assert!(f.heads > 0 && !f.runs.is_empty());
    assert!(f.area > 0.0 && f.covered >= f.area * 0.999, "covered {} of {}", f.covered, f.area);
    assert!(f.issues.is_empty(), "{:?}", &f.issues[..f.issues.len().min(5)]);
    assert!(!f.issues.iter().any(|i| i.contains("parts") || i.contains("open end")));
    // in every room a head serves no more than the area rule of the room's hazard class
    for (k, st) in p.storeys.iter().enumerate() {
        let hs: Vec<(f64, f64)> =
            st.layout.fixtures.iter().filter(|x| x.family == "Sprinkler Head").map(|x| x.at).collect();
        for (i, (r, g)) in st.rooms.iter().zip(&st.layout.rooms).enumerate() {
            if matches!(r.kind, RoomKind::Stair | RoomKind::Lift) || g.polygon.len() < 3 {
                continue;
            }
            let n = hs.iter().filter(|h| inside(&g.polygon, **h)).count();
            let per = area(&g.polygon) / n.max(1) as f64;
            let lim = hazard_of(r.kind).area;
            assert!(n > 0 && per <= lim + 1e-6, "storey {k} room {i} {:?}: {n} heads, {per} m2 each over {lim}", r.kind);
        }
    }
    // risers stand apart, one per pressure zone and riser
    assert!(f.risers.len() >= 2);
    let risers = f.runs.iter().filter(|r| r.kind == FireRun::Riser).count();
    assert_eq!(risers, f.zones.len() * f.risers.len());
    // every run is a catalogue pipe sized for its flow
    assert!(f.runs.iter().all(|r| r.run.pipe.is_some() && r.flow > 0.0));
}

#[test]
fn sprinklers_follow_the_height_rule_and_the_brief() {
    let (_, low) = built(office(3, json!({})));
    assert_eq!(low.fire.heads, 0);
    let (_, asked) = built(office(3, json!({"sprinklers": true})));
    assert!(asked.fire.heads > 0 && asked.fire.issues.is_empty(), "{:?}", asked.fire.issues);
    let (_, off) = built(office(40, json!({"sprinklers": false})));
    assert_eq!(off.fire.heads, 0);
}

#[test]
fn tall_cores_get_more_lifts_and_pressurised_stairs() {
    let (_, low) = built(office(6, json!({"lift": true})));
    assert_eq!(low.lifts.cars, 1);
    let (_, tall) = built(office(48, json!({"lift": true})));
    assert!(tall.lifts.cars > 1, "{:?}", tall.lifts);
    assert!(tall.lifts.wanted >= tall.lifts.cars);
    assert_eq!(tall.storeys[0].layout.shafts.len() as u32, tall.lifts.cars);
    assert!(tall.fire.pressurised);
    let (_, asked) = built(office(6, json!({"lifts": 3})));
    assert_eq!(asked.lifts.cars, 3);
    assert_eq!(asked.storeys[0].layout.shafts.len(), 3);
}

#[test]
fn the_tall_rules_explain_themselves() {
    use ddc_gen::project::why::explain_project;
    let (s, p) = built(office(48, json!({"lift": true, "design": {"facade": "curtain"}})));
    let keys: Vec<&str> = explain_project(&s, &p).iter().map(|w| w.key).collect();
    for k in ["sprinklers", "stair_pressure", "lift_cars", "curtain"] {
        assert!(keys.contains(&k), "{k} missing from {keys:?}");
    }
}

#[test]
fn the_first_forty_blocks_keep_their_slots() {
    use ddc_gen::project::slots::*;
    // references of applied projects: nothing below the tall blocks moved
    assert_eq!((PER_STOREY, LOW_STOREYS, FIXTURES, FIXTURES_PER_STOREY), (1024, 40, 41 * 1024, 2048));
    assert_eq!((PLANT, DUCTS, WATER, ELEC, CIRCUITS), (FIXTURES + 40 * 2048, PLANT + 64, DUCTS + 16384, WATER + 16384, ELEC + 16384));
    assert_eq!(block_base(39), 39 * PER_STOREY);
    assert_eq!(fixture_base(39), FIXTURES + 39 * 2048);
    assert_eq!((basement_block(0), storey_block(39, 0), ROOF), (39, 39, 40 * PER_STOREY));
    // the tall blocks, curtains and services follow each other without overlap
    assert!(SPRINKLER >= CIRCUITS + CIRCUITS_MAX && TALL >= SPRINKLER + SPRINKLER_MAX);
    // the standpipes keep a fixed tail of the sprinkler block
    assert_eq!((STANDPIPE, STANDPIPE + STANDPIPE_MAX), (SPRINKLER + SPRINKLER_RUNS, SPRINKLER + SPRINKLER_MAX));
    assert!(CURTAINS >= TALL + TALL_MAX && TOTAL >= CURTAINS + CURTAINS_ALL);
    assert!(block_base(40) >= TALL && fixture_base(40) >= TALL_FIXTURES && split_block(40) >= TALL_SPLIT);
    assert_eq!((basement_block(0), storey_block(39, 1)), (39, MAX_STOREYS - 1));
    assert_eq!(locate(block_base(60) + 5), Some((60, 5)));
}

/// Distance of `p` along wall `w` from its start, for a straight wall.
fn along(w: &ddc_gen::GWall, p: (f64, f64)) -> f64 {
    let (dx, dy) = (w.b.0 - w.a.0, w.b.1 - w.a.1);
    let len = dx.hypot(dy);
    ((p.0 - w.a.0) * dx + (p.1 - w.a.1) * dy) / len
}

#[test]
fn a_curtain_run_never_spans_a_door() {
    let (_, p) = built(office(3, json!({"design": {"facade": "curtain"}})));
    let mut doors = 0;
    for s in &p.storeys {
        for o in s.layout.openings.iter().filter(|o| o.door) {
            let w = &s.layout.walls[o.wall];
            if w.role != ddc_gen::WallRole::Exterior || w.bulge != 0.0 {
                continue;
            }
            doors += 1;
            let mid = o.along + o.width / 2.0;
            for c in s.curtains.iter().filter(|c| c.wall == o.wall) {
                let (t0, t1) = (along(w, c.a), along(w, c.b));
                let (lo, hi) = (t0.min(t1), t0.max(t1));
                assert!(!(lo + 1e-6 < mid && mid < hi - 1e-6), "curtain {lo:.2}..{hi:.2} spans the door at {mid:.2}");
            }
        }
    }
    assert!(doors > 0, "the office has no exterior door to test against");
}

#[test]
fn the_curtain_slots_hold_and_a_curved_facade_is_one_piece_per_module() {
    use ddc_gen::project::slots::{CURTAINS_MAX, CURTAINS, CURTAINS_ALL, MAX_STOREYS};
    assert_eq!(CURTAINS_ALL, MAX_STOREYS * CURTAINS_MAX);
    let (_, p) = built(office(3, json!({"design": {"facade": "curtain", "curve": 4.0}})));
    for s in &p.storeys {
        assert!(s.curtains.len() <= CURTAINS_MAX as usize);
    }
    let curved: usize = p.storeys[0].curtains.iter().filter(|c| c.name.starts_with("Curtain")).count();
    let (_, flat) = built(office(3, json!({"design": {"facade": "curtain"}})));
    assert!(curved > flat.storeys[0].curtains.len(), "an arc takes chords: {curved}");
    assert!(CURTAINS > 0);
    // a module so small that one storey needs more pieces than the slots hold is refused, naming the way out
    let v = office(2, json!({"design": {"facade": "curtain", "curve": 4.0}, "rules": {"facade.curtain_module": 0.6},
        "footprint": {"width": 200, "depth": 40}}));
    let s = parse_spec(&v).unwrap_or_else(|e| panic!("{e}"));
    let e = build_project(&s).unwrap_err().to_string();
    assert!(e.contains("curtain walls") && e.contains("larger facade module"), "{e}");
}
